import { Group, Mesh, BoxGeometry, PlaneGeometry, Color, PointLight, DirectionalLight, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

const PALETTE = {
  background: '#0b0b10',
  surface: '#16161d',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  gradTop: '#ff4450',
  gradBottom: '#c1121f',
  hairline: '#2a2a33',
  hairlineDim: '#23232b',
};

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'nova-pricing-card';

  const disposables = [];
  const timelines = [];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, fallback) => {
    const found = items.find((i) => i.role === role);
    return found ? found.text : fallback;
  };

  // ---------- BACKDROP (avoid flat void) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(PALETTE.background), color(PALETTE.surface), uv().y.mul(0.6));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new PlaneGeometry(3.6, 3.6);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const shadowUv = uv().sub(vec2(0.5, 0.5));
  const shadowDist = length(shadowUv);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(0.5, 0.0, shadowDist).mul(0.5);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = 0;
  contactShadow.position.set(0, -1.85, -0.4);
  group.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- CARD ROOT (extruded, animated) ----------
  const cardRoot = new Group();
  cardRoot.scale.setScalar(1.04);
  group.add(cardRoot);

  // Border/frame (slightly larger, behind)
  const borderGeo = new BoxGeometry(2.412, 3.212, 0.06);
  const borderMat = new MeshStandardNodeMaterial({
    color: new Color(PALETTE.hairline),
    roughness: 0.6,
    metalness: 0.1,
  });
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.04);
  cardRoot.add(border);
  disposables.push(borderGeo, borderMat);

  // Card body
  const cardGeo = new BoxGeometry(2.4, 3.2, 0.12);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(PALETTE.surface),
    roughness: 0.6,
    metalness: 0.15,
  });
  const card = new Mesh(cardGeo, cardMat);
  cardRoot.add(card);
  disposables.push(cardGeo, cardMat);

  // Machined header strip
  const headerGeo = new BoxGeometry(2.4, 0.08, 0.16);
  const headerMat = new MeshPhysicalNodeMaterial({
    color: new Color('#1c1c24'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  if ('anisotropy' in headerMat) headerMat.anisotropy = 0.6;
  const header = new Mesh(headerGeo, headerMat);
  header.position.set(0, 1.56, 0.02);
  cardRoot.add(header);
  disposables.push(headerGeo, headerMat);

  // ---------- TEXT: TIER NAME ----------
  const tierName = ctx.fontAtlas.createText(findText('tier-name', 'ATELIER RESERVE'), {
    fontSize: 20,
    color: PALETTE.paper,
    align: 'center',
    letterSpacingPx: 1.6,
  });
  tierName.position.set(0, 1.18, 0.08);
  cardRoot.add(tierName);

  // ---------- TEXT: PRICE ----------
  const price = ctx.fontAtlas.createText(findText('price', '$480'), {
    fontSize: 62,
    color: PALETTE.paper,
    align: 'center',
  });
  price.position.set(0, 0.78, 0.08);
  cardRoot.add(price);

  // ---------- TEXT: CAPTION ----------
  const caption = ctx.fontAtlas.createText(findText('caption', 'PER MONTH, BILLED ANNUALLY'), {
    fontSize: 9,
    color: PALETTE.paper,
    align: 'center',
    letterSpacingPx: 1.08,
  });
  caption.position.set(0, 0.52, 0.08);
  cardRoot.add(caption);

  // ---------- FEATURE ROWS ----------
  const featureTexts = items.filter((i) => i.role === 'feature').map((i) => i.text);
  const fallbackFeatures = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];
  const features = featureTexts.length ? featureTexts : fallbackFeatures;

  const rowGeo = new PlaneGeometry(2.0, 0.004);
  const rowMat = new MeshBasicNodeMaterial({ color: new Color(PALETTE.hairlineDim) });
  disposables.push(rowGeo, rowMat);

  const featureRows = [];
  const rowStartY = 0.15;
  const rowSpacing = 0.28;

  features.slice(0, 4).forEach((text, i) => {
    const rowGroup = new Group();
    const targetY = rowStartY - i * rowSpacing;
    rowGroup.position.set(0, targetY, 0.08);

    const label = ctx.fontAtlas.createText(text, {
      fontSize: 13,
      color: PALETTE.paper,
      align: 'left',
      maxWidthPx: 200,
    });
    label.position.set(-1.0, 0, 0);
    rowGroup.add(label);

    if (i > 0) {
      const hairline = new Mesh(rowGeo, rowMat);
      hairline.position.set(0, rowSpacing / 2, -0.01);
      rowGroup.add(hairline);
    }

    cardRoot.add(rowGroup);
    featureRows.push({ group: rowGroup, targetY });
  });

  // ---------- CTA ROW ----------
  const ctaGroup = new Group();
  ctaGroup.position.set(0, -0.92, 0.1);
  cardRoot.add(ctaGroup);

  const ctaGeo = new BoxGeometry(1.4, 0.36, 0.14);
  const ctaMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.2,
    emissive: new Color(PALETTE.accent),
    emissiveIntensity: 1.5,
  });
  ctaMat.colorNode = mix(color(PALETTE.gradBottom), color(PALETTE.gradTop), uv().y);
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaGroup.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);

  const ctaLabel = ctx.fontAtlas.createText(findText('cta-label', 'JOIN THE RESERVE'), {
    fontSize: 13,
    color: PALETTE.ink,
    align: 'center',
    letterSpacingPx: 1.04,
  });
  ctaLabel.position.set(0, 0, 0.08);
  ctaGroup.add(ctaLabel);

  // ---------- LOCAL LIGHTS (node-local rim + machined drag light) ----------
  const rimLight = new PointLight(new Color(PALETTE.accent), 0.9, 8);
  rimLight.position.set(2.2, 1.2, 2.0);
  group.add(rimLight);

  const dragLight = new DirectionalLight(new Color('#e8ecf2'), 0.8);
  dragLight.position.set(-2, 2.2, 3);
  group.add(dragLight);

  // ---------- ANIMATIONS ----------
  const settleTl = gsap.timeline();
  settleTl.to(cardRoot.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  settleTl.to(dragLight.position, {
    x: 1.2,
    duration: 0.9,
    ease: 'power2.out',
  }, 0);
  timelines.push(settleTl);

  featureRows.forEach(({ group: rowGroup, targetY }, i) => {
    rowGroup.position.y = targetY + 0.2;
    const materials = [];
    rowGroup.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
        materials.push(child.material);
      }
    });
    const proxy = { v: 0 };
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(rowGroup.position, { y: targetY, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(proxy, {
      v: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => {
        materials.forEach((m) => { m.opacity = proxy.v; });
      },
    }, 0);
    timelines.push(tl);
  });

  // ---------- CINEMATIC PRIMITIVES ----------
  const appliedPrimitives = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const handler = ctx.primitives[prim.name];
    if (handler) {
      const result = handler(group, prim.params ?? {});
      if (result) appliedPrimitives.push(result);
    }
  }

  // ---------- HANDLERS ----------
  group.userData.handlers = {};

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    appliedPrimitives.forEach((p) => p.cleanup && p.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());

    [tierName, price, caption, ctaLabel].forEach((t) => {
      t.traverse((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose();
      });
    });
    featureRows.forEach(({ group: rowGroup }) => {
      rowGroup.traverse((c) => {
        if (c.geometry && c.geometry !== rowGeo) c.geometry.dispose();
        if (c.material && c.material !== rowMat) c.material.dispose();
      });
    });

    group.remove(rimLight);
    group.remove(dragLight);
  };

  return group;
}
